import os,gzip,collections,re
D='/app/data'
C=collections.Counter()
for fn in sorted(os.listdir(D)):
    b=open(os.path.join(D,fn),'rb').read()
    tags=[]
    if b[:2]==b'\x1f\x8b':
        b=gzip.decompress(b); tags.append('gz')
    if b[:3]==b'\xef\xbb\xbf': tags.append('bom8')
    elif b[:2] in (b'\xff\xfe',b'\xfe\xff'): tags.append('bom16')
    try:
        if b[:2]==b'\xff\xfe' or b[:2]==b'\xfe\xff': t=b.decode('utf-16')
        else: t=b.decode('utf-8-sig')
    except Exception as e:
        tags.append('ERR'); t=b.decode('latin-1')
    dep=fn.split('-')[0]
    for l in t.split('\n'):
        if l.startswith('#') or l.startswith('\x0c'):
            k=re.sub(r'\d+','N',l)
            if dep=='south' and 'LISTING' in l: k='PAGEHDR'
            C[(dep,k)]+=1
    if tags: print(fn,tags)
for k,v in sorted(C.items()): print(v,k)
