import os,gzip,collections,re,csv,json
D='/app/data'
C=collections.Counter()
def shape(s): return re.sub(r'[A-Za-z]','a',re.sub(r'\d','9',s))
for fn in sorted(os.listdir(D)):
    dep=fn.split('-')[0]
    b=open(os.path.join(D,fn),'rb').read()
    if b[:2]==b'\x1f\x8b': b=gzip.decompress(b)
    if b[:2] in (b'\xff\xfe',b'\xfe\xff'): t=b.decode('utf-16')
    else: t=b.decode('latin-1')
    if dep in('east','lakeside','river','west','harbor'):
        delim={'east':',','lakeside':',','river':'\t','west':';','harbor':'|'}[dep]
        lines=t.split('\n'); i=0; hdr=None;mode=''
        while i<len(lines):
            l=lines[i]; i+=1
            if not l.strip(): continue
            if l.startswith('#'):
                m=re.match(r'# (dates|date format): (.*)',l)
                if m: mode=m.group(2)
                continue
            while l.count('"')%2 and i<len(lines): l+='\n'+lines[i]; i+=1
            f=next(csv.reader([l],delimiter=delim)) if dep in('east','lakeside') else l.rstrip('\r').split(delim)
            if f[0] in('id','t','rec'): hdr=f; continue
            if f[0]=='TOTAL': continue
            d=dict(zip(hdr,f))
            for k in ('shipped','booked','date','weight','gross','gross_kg','status','state','type','typ','kind','rec','t'):
                if k in d:
                    v=d[k]
                    if k in('status','state','type','typ','kind','rec','t'): C[(dep,k,v)]+=1
                    elif k=='weight' and dep=='west': C[(dep,k,shape(v))]+=1
                    else: C[(dep,k,mode if 'ship' in k or k=='date' else '',shape(v))]+=1
            C[(dep,'idshape',shape(f[hdr.index('id')] if 'id' in hdr else f[hdr.index('ref')]))]+=1
for k,v in sorted(C.items(),key=str): print(v,k)
